-- Costa Rican sport-fishing rules per species, shown as a tag in the app.
-- release   = the law requires releasing it (billfish: INCOPESCA AJDIP/280-2014 art. 6, Pacific zones).
-- regulated = it may be kept under legal limits (minimum size, closed season, finning ban...).
-- null      = no species-specific rule found (general rules like the 5-fish trip limit still apply).
alter table public.species
  add column if not exists regulation text check (regulation in ('release', 'regulated')),
  add column if not exists regulation_note_es text,
  add column if not exists regulation_note_en text,
  add column if not exists regulation_source_url text;

update public.species s
set regulation = v.reg, regulation_note_es = v.es, regulation_note_en = v.en, regulation_source_url = v.src
from (values
  ('Parachromis dovii', null, null, null, null),
  ('Brycon guatemalensis', null, null, null, null),
  ('Centropomus undecimalis', null, 'No hay talla mínima nacional para el róbalo del Caribe. En el Refugio Barra del Colorado (SINAC) solo se pesca con caña o cuerda, los martes está cerrado y las lagunas internas están en veda del 1 de octubre al 31 de enero.', 'There is no national minimum size for Caribbean common snook. In the Barra del Colorado Wildlife Refuge (SINAC) only rod or handline is allowed, Tuesdays are closed, and inner lagoons are closed Oct 1–Jan 31.', 'https://www.acto.go.cr/wp-content/uploads/2026/01/GPRPRNVSBC.pdf'),
  ('Megalops atlanticus', 'regulated', 'Especie de interés turístico-deportivo (Ley de Pesca 8436, art. 76): no se puede vender y se prohíbe su pesca dirigida con carnada viva en las zonas que fije INCOPESCA (Reglamento 36782, art. 57). INCOPESCA pide liberarlo y casi todos los pescadores lo sueltan.', 'Declared a tourist-sport species (Fisheries Law 8436, art. 76): it cannot be sold, and targeting it with live bait is banned in zones set by INCOPESCA (Regulation 36782, art. 57). INCOPESCA asks anglers to release it, and nearly all do.', 'https://www.incopesca.go.cr/acerca_incopesca/normativa/ley_de_pesca_y_acuicultura_ley_n_8436.pdf'),
  ('Lutjanus campechanus', null, null, null, null),
  ('Lutjanus guttatus', 'regulated', 'Talla mínima legal de captura: 30 cm (AJDIP/026-2018 de INCOPESCA). Si es más pequeño, libéralo.', 'Legal minimum catch size: 30 cm (INCOPESCA AJDIP/026-2018). Release smaller fish.', 'https://faolex.fao.org/docs/pdf/cos216416.pdf'),
  ('Coryphaena hippurus', 'regulated', 'Talla mínima legal de captura: 80 cm (AJDIP/026-2018 de INCOPESCA). En pesca deportiva no puedes vender la captura.', 'Legal minimum catch size: 80 cm (INCOPESCA AJDIP/026-2018). Sport catches cannot be sold.', 'https://faolex.fao.org/docs/pdf/cos216416.pdf'),
  ('Makaira nigricans', 'release', 'Si lo capturas vivo en pesca deportiva o turística en el Pacífico (golfos y primeras 30 millas), la ley obliga a liberarlo sin sacarlo del agua, cortando la línea cerca del anzuelo (AJDIP/280-2014 de INCOPESCA, art. 6). Además, no puedes subirlo a la borda para fotos ni usar bichero (art. 7).', 'If you catch one alive while sport or charter fishing in the Pacific (gulfs and first 30 nautical miles), the law requires releasing it without taking it out of the water, cutting the line near the hook (INCOPESCA AJDIP/280-2014, art. 6). Boating it for photos or using a gaff is also prohibited (art. 7).', 'https://www.incopesca.go.cr/acerca_incopesca/transparencia_institucional/jerarcas_decisiones/acuerdos/AJDIP-280-2014_Medidas_ordenamiento_carnada_viva.pdf'),
  ('Kajikia audax', 'release', 'Si lo capturas vivo en pesca deportiva o turística en el Pacífico (golfos y primeras 30 millas), la ley obliga a liberarlo sin sacarlo del agua, cortando la línea cerca del anzuelo (AJDIP/280-2014 de INCOPESCA, art. 6). Además, no puedes subirlo a la borda para fotos ni usar bichero (art. 7).', 'If you catch one alive while sport or charter fishing in the Pacific (gulfs and first 30 nautical miles), the law requires releasing it without taking it out of the water, cutting the line near the hook (INCOPESCA AJDIP/280-2014, art. 6). Boating it for photos or using a gaff is also prohibited (art. 7).', 'https://www.incopesca.go.cr/acerca_incopesca/transparencia_institucional/jerarcas_decisiones/acuerdos/AJDIP-280-2014_Medidas_ordenamiento_carnada_viva.pdf'),
  ('Istiophorus platypterus', 'release', 'Si lo capturas vivo en pesca deportiva o turística en el Pacífico (golfos y primeras 30 millas), la ley obliga a liberarlo sin sacarlo del agua, cortando la línea cerca del anzuelo (AJDIP/280-2014 de INCOPESCA, art. 6). Además, no puedes subirlo a la borda para fotos ni usar bichero (art. 7).', 'If you catch one alive while sport or charter fishing in the Pacific (gulfs and first 30 nautical miles), the law requires releasing it without taking it out of the water, cutting the line near the hook (INCOPESCA AJDIP/280-2014, art. 6). Boating it for photos or using a gaff is also prohibited (art. 7).', 'https://www.incopesca.go.cr/acerca_incopesca/transparencia_institucional/jerarcas_decisiones/acuerdos/AJDIP-280-2014_Medidas_ordenamiento_carnada_viva.pdf'),
  ('Acanthocybium solandri', null, null, null, null),
  ('Thunnus albacares', 'regulated', 'Talla mínima legal de captura: 60 cm (AJDIP/026-2018 de INCOPESCA).', 'Legal minimum catch size: 60 cm (INCOPESCA AJDIP/026-2018).', 'https://faolex.fao.org/docs/pdf/cos216416.pdf'),
  ('Cynoscion squamipinnis', 'regulated', 'Talla mínima legal de captura: 33 cm (AJDIP/026-2018 de INCOPESCA). En el Golfo de Nicoya rige una veda anual del 1 de mayo al 31 de julio.', 'Legal minimum catch size: 33 cm (INCOPESCA AJDIP/026-2018). The Gulf of Nicoya has an annual closed season from May 1 to July 31.', 'https://faolex.fao.org/docs/pdf/cos216416.pdf'),
  ('Caranx hippos', null, null, null, null),
  ('Trachinotus falcatus', null, null, null, null),
  ('Lutjanus cyanopterus', null, null, null, null),
  ('Scomberomorus maculatus', null, 'La sierra del Pacífico (Scomberomorus sierra) tiene una talla mínima de 50 cm (AJDIP/026-2018); para S. maculatus no hay una regla específica.', 'The Pacific sierra (Scomberomorus sierra) has a 50 cm minimum size (AJDIP/026-2018); there is no specific rule for S. maculatus.', 'https://faolex.fao.org/docs/pdf/cos216416.pdf'),
  ('Sphyraena barracuda', null, 'La barracuda del Pacífico (Sphyraena ensis) tiene una talla mínima de 38 cm (AJDIP/026-2018); para S. barracuda no hay una regla específica.', 'The Pacific barracuda (Sphyraena ensis) has a 38 cm minimum size (AJDIP/026-2018); there is no specific rule for S. barracuda.', 'https://faolex.fao.org/docs/pdf/cos216416.pdf'),
  ('Epinephelus quinquefasciatus', null, 'No encontramos una prohibición legal en Costa Rica, pero es un mero gigante amenazado; te recomendamos liberarlo.', 'No legal ban was found in Costa Rica, but it is a threatened giant grouper; releasing it is recommended.', null),
  ('Carcharhinus leucas', 'regulated', 'Si lo retienes, debe llegar a tierra con las aletas adheridas al cuerpo; el aleteo está prohibido (Ley de Pesca 8436, art. 40). Desde 2023 está en el Apéndice II de CITES, lo que controla su comercio internacional.', 'If kept, it must be landed with fins naturally attached; finning is banned (Fisheries Law 8436, art. 40). Since 2023 it is on CITES Appendix II, which controls its international trade.', 'https://www.incopesca.go.cr/acerca_incopesca/normativa/ley_de_pesca_y_acuicultura_ley_n_8436.pdf'),
  ('Gerres cinereus', null, null, null, null),
  ('Joturus pichardi', 'regulated', 'Veda para la pesca deportiva y turística en toda la cuenca del río Pacuare durante octubre de cada año. El resto del año solo se permite caña, carrete o cuerda de mano (AJDIP/237-2015 de INCOPESCA).', 'Sport and charter fishing is closed every October throughout the Pacuare River basin. The rest of the year only rod and reel or handline is allowed (INCOPESCA AJDIP/237-2015).', 'https://incopesca.go.cr/acerca_incopesca/transparencia_institucional/jerarcas_decisiones/acuerdos/AJDIP-237-2015_Establece_veda_pez_bobo_cuenca_rio_pacuare.pdf'),
  ('Oreochromis niloticus', null, 'Es una especie introducida. En el Refugio Barra del Colorado no se debe devolver al agua.', 'It is an introduced species. In the Barra del Colorado Refuge it must not be returned to the water.', 'https://www.acto.go.cr/wp-content/uploads/2026/01/GPRPRNVSBC.pdf'),
  ('Rhamdia guatemalensis', null, null, null, null),
  ('Agonostomus monticola', null, null, null, null),
  ('Mayaheros urophthalmus', null, null, null, null),
  ('Atractosteus tropicus', 'regulated', 'En el Refugio Barra del Colorado (SINAC) está en veda del 1 de marzo al 31 de julio, con un máximo de 2 piezas por licencia y una talla mínima recomendada de 80 cm. Además figura en la lista nacional de especies con poblaciones reducidas.', 'In the Barra del Colorado Refuge (SINAC) it is closed March 1–July 31, with a maximum of 2 fish per licence and a recommended minimum of 80 cm. It is also on the national list of species with reduced populations.', 'https://www.acto.go.cr/wp-content/uploads/2026/01/GPRPRNVSBC.pdf'),
  ('Haemulon plumierii', null, null, null, null),
  ('Nematistius pectoralis', null, 'No hay obligación legal de liberarlo, pero la costumbre es soltarlo y INCOPESCA lo recomienda en los torneos. En 2014 se propuso hacerlo de captura y liberación, pero esa reforma no está vigente en el Reglamento.', 'Release is not legally required, but it is customary and INCOPESCA recommends it at tournaments. A 2014 proposal to make it catch-and-release only is not in force in the Regulation.', 'https://www.incopesca.go.cr/acerca_incopesca/transparencia_institucional/jerarcas_decisiones/acuerdos/AJDIP-086-2014%20Aprueba-propuesta-modificacion-reglamento-lepac-36782.pdf'),
  ('Mugil cephalus', null, null, null, null),
  ('Strongylura notata', null, null, null, null),
  ('Caranx crysos', null, null, null, null),
  ('Xiphias gladius', 'release', 'Si lo capturas vivo en pesca deportiva o turística en el Pacífico (golfos y primeras 30 millas), la ley obliga a liberarlo sin sacarlo del agua, cortando la línea cerca del anzuelo (AJDIP/280-2014 de INCOPESCA, art. 6). Además, no puedes subirlo a la borda para fotos ni usar bichero (art. 7).', 'If you catch one alive while sport or charter fishing in the Pacific (gulfs and first 30 nautical miles), the law requires releasing it without taking it out of the water, cutting the line near the hook (INCOPESCA AJDIP/280-2014, art. 6). Boating it for photos or using a gaff is also prohibited (art. 7).', 'https://www.incopesca.go.cr/acerca_incopesca/transparencia_institucional/jerarcas_decisiones/acuerdos/AJDIP-280-2014_Medidas_ordenamiento_carnada_viva.pdf'),
  ('Rachycentron canadum', null, null, null, null),
  ('Trachinotus carolinus', null, null, null, null),
  ('Epinephelus labriformis', null, null, null, null),
  ('Dasyatis americana', null, null, null, null),
  ('Sardinella aurita', null, null, null, null),
  ('Oncorhynchus mykiss', null, 'No encontramos una veda vigente. Un decreto antiguo (25729-MINAE, 1997) fijaba veda en ríos del 1 de febrero al 30 de abril, 5 piezas al día y 25 cm de talla mínima, pero ya no está vigente.', 'No current closed season was found. An old decree (25729-MINAE, 1997) set a river closure from Feb 1 to Apr 30, 5 fish/day and a 25 cm minimum, but it has expired.', 'https://faolex.fao.org/docs/pdf/cos9596.pdf'),
  ('Poecilia gillii', null, null, null, null)
) as v(sci, reg, es, en, src)
where s.scientific_name = v.sci;
